package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.*;
import static org.jlinalg.cli.FollowupSupport.hash;

/** Captured UTF-8 requests for native legacy TSS enrichment and gene activity. */
public final class SignacAnnotationsRequestCli {
    private SignacAnnotationsRequestCli() { }
    private static final String ACTION="Read WARNINGS.md, analysis-status.json, operation.json and the original/captured request. Preserve failed attempts, correct the named annotation, coordinate, mode, population or capacity cause and rerun to a NEW output directory. These native operations need no R installation. Legacy TSS modes differ; gene activity is a fragment-count proxy, not measured gene expression. Full Signac integration remains incomplete.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(out,"SignacAnnotationsRequestCli --request ASCII_PATH_TO_UTF8_JSON\nSchema1 modes: TSS_FAST, TSS_PROFILE, GENE_ACTIVITY, VERIFY.\nPut exact Unicode data paths/IDs inside UTF-8 JSON/tables.\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON");Path path=Path.of(args[1]).toAbsolutePath().normalize();Map<String,Object> request=object(read(path));
            if("VERIFY".equals(request.get("mode"))){keys(request,Set.of("schema_version","mode","analysis"));schema(request);verify(resolve(path.getParent(),text(request,"analysis"),false));emit(out,"Verified captured native Signac annotation calculation");return 0;}
            validate(request);Path destination=resolve(path.getParent(),text(request,"out"),false);int[] code={0};
            FollowupSupport.transaction(Map.of("out",destination.toString()),"signac-native-annotations-development",(stage,manifest)->{
                List<SignacFragments.Warning> warnings=new ArrayList<>();try{
                    String before=hash(path);Files.copy(path,stage.resolve("source-request.json"));if(!before.equals(hash(path))||!before.equals(hash(stage.resolve("source-request.json"))))throw new IOException("Request changed during capture");
                    Map<String,Object> captured=capture(request,path.getParent(),stage);Files.writeString(stage.resolve("request.json"),NextflowJson.json(captured),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);execute(captured,stage,new WriteSink(stage),stage.resolve("sort"),warnings);
                    manifest.put("analysis_status",warnings.isEmpty()?"completed":"completed-with-warnings");manifest.put("mode",request.get("mode"));manifest.put("source_request_sha256",before);manifest.put("full_Signac_workflow_available",false);
                }catch(Exception error){code[0]=2;manifest.put("analysis_status","failed");manifest.put("error",error.toString());warnings.add(new SignacFragments.Warning("FAIL2_NO_RESULT_ADMITTED",error.toString(),ACTION));}
                Files.writeString(stage.resolve("WARNINGS.md"),warningText(stage,warnings,code[0]!=0),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.writeString(stage.resolve("analysis-status.json"),NextflowJson.json(Map.of("status",manifest.get("analysis_status"))),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.writeString(stage.resolve("manifest.json"),NextflowJson.json(manifest),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            });seal(destination);if(code[0]==0){verify(destination);emit(out,"Completed native Signac "+request.get("mode")+": "+destination);}else emit(err,"FAIL2 — no successful native result admitted: "+destination);emit(err,"WARNINGS / REQUIRED ACTION: "+destination.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        }catch(Exception error){emit(err,"FAIL2 — native annotation request or verification failed: "+error+"\n"+ACTION);return 2;}
    }
    private static void schema(Map<String,Object> r)throws IOException{if(!(r.get("schema_version") instanceof Number n)||n.doubleValue()!=1)throw new IOException("Require schema_version1");}
    private static void validate(Map<String,Object> r)throws IOException{
        schema(r);String mode=text(r,"mode");Set<String> allowed=new HashSet<>(Set.of("schema_version","mode","out","sources","object_cells","object_cells_file","genome_build","process_n"));
        if(mode.equals("GENE_ACTIVITY"))allowed.addAll(Set.of("annotation","features","features_file","biotypes","max_width","upstream","downstream","gene_ids","sort_records"));else if(Set.of("TSS_FAST","TSS_PROFILE").contains(mode))allowed.addAll(Set.of("positions","annotation","first_n","region_extension","cells","profile_values"));else throw new IOException("Unknown annotation request mode");keys(r,allowed);text(r,"out");text(r,"genome_build");
        if(r.containsKey("object_cells")==r.containsKey("object_cells_file"))throw new IOException("Choose exactly one object cell universe representation");
        if(mode.equals("GENE_ACTIVITY")){text(r,"annotation");if(r.containsKey("features")&&r.containsKey("features_file"))throw new IOException("Choose one gene feature-list representation");integer(r,"sort_records",100000,1,1000000);integer(r,"upstream",2000,0,1000000);integer(r,"downstream",0,0,1000000);bool(r,"gene_ids",false);if(r.get("max_width")!=null)decimal(r.get("max_width"));}
        else{if(r.containsKey("positions")==r.containsKey("annotation"))throw new IOException("Choose explicit TSS positions or a flattened gene annotation");integer(r,"region_extension",1000,0,1000000);if(r.containsKey("first_n"))integer(r,"first_n",1,1,2000000);integer(r,"profile_values",20000000,1,100000000);}
        integer(r,"process_n",2000,1,2000000);List<?> sources=list(r.get("sources"));if(sources.isEmpty())throw new IOException("Require fragment sources");for(Object item:sources){Map<String,Object> source=object(item);keys(source,Set.of("path","map","map_file"));text(source,"path");if(source.containsKey("map")&&source.containsKey("map_file"))throw new IOException("Choose one mapping representation");if(source.containsKey("map"))for(Object pair:list(source.get("map"))){var value=object(pair);keys(value,Set.of("cell","barcode"));text(value,"cell");text(value,"barcode");}}
    }
    private static final List<String> INPUT_FIELDS=List.of("positions","annotation","object_cells_file","features_file");
    private static Map<String,Object> capture(Map<String,Object> request,Path parent,Path stage)throws IOException{
        Files.createDirectory(stage.resolve("input"));Map<Path,String> copies=new LinkedHashMap<>();Map<String,Object> result=new LinkedHashMap<>(request);result.put("out",".");for(String key:INPUT_FIELDS)if(result.containsKey(key))result.put(key,copy(text(result,key),parent,stage,copies));List<Map<String,Object>> sources=new ArrayList<>();
        for(Object item:list(result.get("sources"))){var source=new LinkedHashMap<>(object(item));source.put("path",copy(text(source,"path"),parent,stage,copies));if(source.containsKey("map_file"))source.put("map_file",copy(text(source,"map_file"),parent,stage,copies));sources.add(source);}result.put("sources",sources);return result;
    }
    private static String copy(String value,Path parent,Path stage,Map<Path,String> copies)throws IOException{Path source=resolve(parent,value,false);String old=copies.get(source);if(old!=null)return old;if(!Files.isRegularFile(source))throw new IOException("Input unavailable: "+source);String target="input/file-"+copies.size(),before=hash(source);Files.copy(source,stage.resolve(target));if(!before.equals(hash(source))||!before.equals(hash(stage.resolve(target))))throw new IOException("Input changed during capture");copies.put(source,target);return target;}
    @FunctionalInterface private interface Line {void add(String value)throws IOException;}
    @FunctionalInterface private interface Table {void write(Line line)throws IOException;}
    private interface Sink {void table(String name,Table value)throws IOException;}
    private record WriteSink(Path root)implements Sink{public void table(String name,Table value)throws IOException{try(var out=Files.newBufferedWriter(root.resolve(name),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){value.write(line->{out.write(line);out.write('\n');});}}}
    private record CheckSink(Path root)implements Sink{public void table(String name,Table value)throws IOException{try(var in=Files.newBufferedReader(root.resolve(name),StandardCharsets.UTF_8)){value.write(line->{if(!line.equals(in.readLine()))throw new IOException("Recomputed annotation result differs: "+name);});if(in.readLine()!=null)throw new IOException("Extra annotation result rows: "+name);}}}
    private static void execute(Map<String,Object> r,Path root,Sink sink,Path scratch,List<SignacFragments.Warning> warnings)throws IOException{
        validate(r);var defaults=SignacFragments.Limits.defaults();String mode=text(r,"mode");List<String> cells=ids(r,"object_cells","object_cells_file",root,true);List<SignacFragments.Source> sources=sources(r,root);List<Map<String,Object>> passes=new ArrayList<>();
        if(mode.equals("GENE_ACTIVITY")){
            int memory=(int)integer(r,"sort_records",100000,1,1000000);var limits=new SignacFragments.Limits(defaults.features(),defaults.cells(),defaults.nonzeroValues(),defaults.records(),defaults.contributions(),defaults.decodedBytes(),defaults.lineBytes(),memory);
            List<String> biotypes=r.containsKey("biotypes")?(r.get("biotypes")==null?null:strings(r.get("biotypes"))):List.of("protein_coding");Double max=r.containsKey("max_width")?(r.get("max_width")==null?null:decimal(r.get("max_width"))):500000.0;
            var options=new SignacGeneActivity.Options(ids(r,"features","features_file",root,false),biotypes,max,(int)integer(r,"upstream",2000,0,1000000),(int)integer(r,"downstream",0,0,1000000),(int)integer(r,"process_n",2000,1,2000000),bool(r,"gene_ids",false));
            var result=SignacGeneActivity.geneActivity(sources,annotations(resolve(root,text(r,"annotation"),true)),cells,options,scratch,limits,()->false);warnings.addAll(result.warnings());var matrix=result.matrix();int[] pointers=matrix.pointers(),rows=matrix.rows();long[] values=matrix.values();
            sink.table("matrix.mtx",line->{line.add("%%MatrixMarket matrix coordinate integer general");line.add(matrix.features().size()+" "+matrix.cells().size()+" "+values.length);for(int col=0;col<matrix.cells().size();col++)for(int k=pointers[col];k<pointers[col+1];k++)line.add((rows[k]+1)+" "+(col+1)+" "+values[k]);});sink.table("features.tsv",line->{for(String id:matrix.features())line.add(id);});sink.table("cells.tsv",line->{for(String id:matrix.cells())line.add(id);});
            sink.table("selected-genes.tsv",line->{line.add("chromosome\tstart\tend\tstrand\tgene_id\tgene_name\tgene_biotype");for(var row:result.transcripts())line.add(row.chromosome()+"\t"+row.start()+"\t"+row.end()+"\t"+row.strand()+"\t"+row.geneId()+"\t"+row.geneName()+"\t"+row.biotype());});
            Set<String> universe=new HashSet<>(cells);int at=0;for(int i=0;i<sources.size();i++){var source=sources.get(i);if(source.map()==null||source.map().stream().anyMatch(cell->universe.contains(cell.cell())))passes.add(scan(i,"fragment-quantification",matrix.scans().get(at++)));}if(at!=matrix.scans().size())throw new IOException("Internal source scan identity differs");
        }else{
            List<SignacTssEnrichment.Position> positions=r.containsKey("positions")?positions(resolve(root,text(r,"positions"),true)):SignacGeneActivity.tssPositions(annotations(resolve(root,text(r,"annotation"),true)),true,()->false);
            var options=new SignacTssEnrichment.Options(mode.equals("TSS_FAST"),(int)integer(r,"process_n",2000,1,2000000),(int)integer(r,"region_extension",1000,0,1000000),r.get("first_n")==null?null:(int)integer(r,"first_n",1,1,2000000),r.get("cells")==null?null:strings(r.get("cells")),integer(r,"profile_values",20000000,1,100000000));
            var result=SignacTssEnrichment.enrich(sources,positions,cells,options,defaults,()->false);warnings.addAll(result.warnings());sink.table("tss.tsv",line->{line.add("cell\tTSS.enrichment\tscore_kind\tTSS.percentile\tpercentile_kind");for(var row:result.scores())line.add(row.cell()+"\t"+number(row.enrichment())+"\t"+row.enrichment().kind()+"\t"+number(row.percentile())+"\t"+row.percentile().kind());});
            sink.table("selected-tss.tsv",line->{line.add("chromosome\tstart\tend\tstrand\tsequence_length");for(var row:result.selectedPositions())line.add(row.chromosome()+"\t"+row.start()+"\t"+row.end()+"\t"+row.strand()+"\t"+(row.sequenceLength()==null?".":row.sequenceLength()));});
            if(result.profile()!=null){var profile=result.profile();long[][] raw=profile.raw();double[][] normalized=profile.normalized();sink.table("profile.tsv",line->{line.add("row\tcell\tposition\traw_count\tnormalized\tnumber_kind");for(int row=0;row<normalized.length;row++)for(int col=0;col<normalized[row].length;col++){double value=normalized[row][col];line.add((row+1)+"\t"+profile.cells().get(row)+"\t"+profile.positions().get(col)+"\t"+(row<raw.length?Long.toString(raw[row][col]):"")+"\t"+Double.toString(value)+"\tFINITE");}});}
            for(var pass:result.passes())passes.add(scan(pass.source(),pass.phase(),pass.scan()));
        }
        Map<String,Object> operation=new LinkedHashMap<>();operation.put("mode",mode);operation.put("profile","native-legacy-contracts-validated-against-original-Signac-1.17.1");operation.put("genome_build",r.get("genome_build"));operation.put("passes",passes);operation.put("warning_codes",warnings.stream().map(SignacFragments.Warning::code).toList());sink.table("operation.json",line->line.add(NextflowJson.json(operation)));
    }
    private static Map<String,Object> scan(int source,String phase,SignacFragments.Scan value){return Map.of("source",source,"phase",phase,"records",value.records(),"decoded_bytes",value.decodedBytes(),"compressed",value.compressed(),"prefix_only",value.prefixOnly(),"chromosomes",value.chromosomes());}
    private static List<SignacFragments.Source> sources(Map<String,Object> r,Path root)throws IOException{List<SignacFragments.Source> result=new ArrayList<>();for(Object item:list(r.get("sources"))){var source=object(item);List<SignacFragments.Cell> map=null;if(source.containsKey("map_file")){map=new ArrayList<>();for(String[] row:rows(resolve(root,text(source,"map_file"),true),"cell\tbarcode",2))map.add(new SignacFragments.Cell(row[0],row[1]));}else if(source.containsKey("map")){map=new ArrayList<>();for(Object pair:list(source.get("map"))){var value=object(pair);map.add(new SignacFragments.Cell(text(value,"cell"),text(value,"barcode")));}}result.add(new SignacFragments.Source(resolve(root,text(source,"path"),true),map));}return result;}
    private static List<SignacGeneActivity.Annotation> annotations(Path path)throws IOException{List<SignacGeneActivity.Annotation> result=new ArrayList<>();for(String[] row:rows(path,"chromosome\tstart\tend\tstrand\tgene_id\tgene_name\tgene_biotype",7))result.add(new SignacGeneActivity.Annotation(row[0],Integer.parseInt(row[1]),Integer.parseInt(row[2]),row[3],row[4],row[5],row[6]));return result;}
    private static List<SignacTssEnrichment.Position> positions(Path path)throws IOException{List<SignacTssEnrichment.Position> result=new ArrayList<>();for(String[] row:rows(path,"chromosome\tstart\tend\tstrand\tsequence_length",5))result.add(new SignacTssEnrichment.Position(row[0],Integer.parseInt(row[1]),Integer.parseInt(row[2]),row[3],row[4].equals(".")?null:Integer.valueOf(row[4])));return result;}
    private static List<String[]> rows(Path path,String header,int columns)throws IOException{if(Files.size(path)>1000000000L)throw new IOException("Excessive annotation/position/map input");List<String[]> result=new ArrayList<>();try(var in=Files.newBufferedReader(path,StandardCharsets.UTF_8)){if(!header.equals(in.readLine()))throw new IOException("Expected TSV header: "+header);String line;while((line=in.readLine())!=null){if(line.length()>32768||result.size()>=2000000)throw new IOException("Excessive input rows/line");String[] fields=line.split("\t",-1);if(fields.length!=columns)throw new IOException("Ragged annotation/position/map table");result.add(fields);}}return result;}
    private static List<String> ids(Map<String,Object> r,String inline,String file,Path root,boolean required)throws IOException{if(r.containsKey(file)){List<String> result=new ArrayList<>();try(var in=Files.newBufferedReader(resolve(root,text(r,file),true),StandardCharsets.UTF_8)){String value;while((value=in.readLine())!=null){if(value.length()>16384||result.size()>=2000000)throw new IOException("Excessive ID file");result.add(value);}}return result;}if(r.get(inline)!=null)return strings(r.get(inline));if(required)throw new IOException("Missing object cell universe");return null;}
    private static String number(SignacFragmentQc.Value value){return switch(value.kind()){case FINITE->Double.toString(value.value());case POSITIVE_INFINITY->"Inf";case NAN->"NaN";case NA->"NA";};}
    private static String warningText(Path root,List<SignacFragments.Warning> warnings,boolean failed){return "# "+(failed?"FAIL2 — NATIVE ANNOTATION ANALYSIS FAILED":"NATIVE SIGNAC ANNOTATION WARNINGS")+"\n\n"+warnings.stream().map(w->w.code()+": "+w.message().replace(root.toString(),"CAPTURED_DIRECTORY").replace('\\','/')+"\n\nRequired action: "+w.requiredAction()).collect(java.util.stream.Collectors.joining("\n\n"))+"\n\n"+ACTION+"\n";}
    private static Object read(Path path)throws IOException{if(!Files.isRegularFile(path)||Files.size(path)>1000000)throw new IOException("Request/manifest unavailable or exceeds one million bytes");return SimpleJson.parse(Files.readString(path,StandardCharsets.UTF_8));}
    private static Map<String,Object> object(Object value)throws IOException{if(!(value instanceof Map<?,?> map))throw new IOException("Expected JSON object");Map<String,Object> result=new LinkedHashMap<>();for(var entry:map.entrySet())result.put((String)entry.getKey(),entry.getValue());return result;}
    private static List<?> list(Object value)throws IOException{if(!(value instanceof List<?> values))throw new IOException("Expected JSON array");return values;}
    private static List<String> strings(Object value)throws IOException{List<String> result=new ArrayList<>();for(Object item:list(value))result.add(string(item));return result;}
    private static String string(Object value)throws IOException{if(!(value instanceof String s)||s.isBlank())throw new IOException("Require nonblank string");return s;}
    private static String text(Map<String,Object> r,String key)throws IOException{return string(r.get(key));}
    private static void keys(Map<String,Object> r,Set<String> allowed)throws IOException{for(String key:r.keySet())if(!allowed.contains(key))throw new IOException("Unknown request field: "+key);}
    private static boolean bool(Map<String,Object> r,String key,boolean fallback)throws IOException{Object value=r.get(key);if(value==null)return fallback;if(!(value instanceof Boolean b))throw new IOException(key+" must be boolean");return b;}
    private static double decimal(Object value)throws IOException{if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()<0)throw new IOException("Require finite nonnegative numeric width");return n.doubleValue();}
    private static long integer(Map<String,Object> r,String key,long fallback,long min,long max)throws IOException{Object value=r.get(key);if(value==null)return fallback;if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=Math.rint(n.doubleValue())||n.doubleValue()<min||n.doubleValue()>max)throw new IOException(key+" must be an integer within bounds");return n.longValue();}
    private static Path resolve(Path parent,String value,boolean captured)throws IOException{Path path=parent.resolve(Path.of(value)).toAbsolutePath().normalize();if(captured&&(!path.startsWith(parent)||Files.isSymbolicLink(path)))throw new IOException("Captured path escapes its bundle");return path;}
    private static void seal(Path root)throws IOException{Path file=root.resolve("artifact-checksums.tsv");try(var paths=Files.walk(root);var out=Files.newBufferedWriter(file,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){out.write("sha256\tpath\n");for(Path path:paths.filter(Files::isRegularFile).filter(p->!p.equals(file)).sorted().toList())out.write(hash(path)+"\t"+root.relativize(path).toString().replace('\\','/')+"\n");}}
    private static void checkCapture(Map<String,Object> original,Map<String,Object> current)throws IOException{validate(original);Map<String,Object> expected=new LinkedHashMap<>(original);expected.put("out",".");for(String key:INPUT_FIELDS)if(expected.containsKey(key)){capturedInput(current.get(key));expected.put(key,current.get(key));}List<?> old=list(original.get("sources")),now=list(current.get("sources"));if(old.size()!=now.size())throw new IOException("Changed source count");List<Map<String,Object>> sources=new ArrayList<>();for(int i=0;i<old.size();i++){var source=new LinkedHashMap<>(object(old.get(i)));var copy=object(now.get(i));capturedInput(copy.get("path"));source.put("path",copy.get("path"));if(source.containsKey("map_file")){capturedInput(copy.get("map_file"));source.put("map_file",copy.get("map_file"));}sources.add(source);}expected.put("sources",sources);if(!expected.equals(current))throw new IOException("Captured options differ from original request");}
    private static void capturedInput(Object value)throws IOException{if(!string(value).matches("input/file-[0-9]+"))throw new IOException("Noncanonical captured input path");}
    private static void verify(Path root)throws IOException{
        Path inventory=root.resolve("artifact-checksums.tsv");List<String> lines=Files.readAllLines(inventory,StandardCharsets.UTF_8);if(lines.isEmpty()||!lines.get(0).equals("sha256\tpath"))throw new IOException("Missing artifact inventory");Set<String> seen=new HashSet<>();for(String line:lines.subList(1,lines.size())){String[] fields=line.split("\t",-1);if(fields.length!=2||!fields[0].matches("[0-9a-f]{64}")||fields[1].contains(":")||fields[1].contains("\\")||Arrays.stream(fields[1].split("/",-1)).anyMatch(s->Set.of("",".","..").contains(s)))throw new IOException("Unsafe artifact inventory");Path path=root.resolve(fields[1]);if(!seen.add(fields[1])||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||!hash(path).equals(fields[0]))throw new IOException("Artifact integrity mismatch");}
        try(var paths=Files.walk(root)){for(Path path:paths.toList()){if(Files.isSymbolicLink(path))throw new IOException("Captured symlink forbidden");if(Files.isRegularFile(path)&&!path.equals(inventory)&&!seen.contains(root.relativize(path).toString().replace('\\','/')))throw new IOException("Uninventoried artifact");}}
        var manifest=object(read(root.resolve("manifest.json")));var status=object(read(root.resolve("analysis-status.json")));if(!Set.of("completed","completed-with-warnings").contains(manifest.get("analysis_status"))||!Objects.equals(status.get("status"),manifest.get("analysis_status")))throw new IOException("Analysis did not complete");var request=object(read(root.resolve("request.json")));checkCapture(object(read(root.resolve("source-request.json"))),request);if(!Objects.equals(manifest.get("mode"),request.get("mode"))||!Boolean.FALSE.equals(manifest.get("full_Signac_workflow_available"))||!Objects.equals(manifest.get("source_request_sha256"),hash(root.resolve("source-request.json"))))throw new IOException("Manifest request binding differs");
        Path temporary=Files.createTempDirectory("omicsmatic-signac-annotation-verify-");List<SignacFragments.Warning> warnings=new ArrayList<>();try{execute(request,root,new CheckSink(root),temporary.resolve("sort"),warnings);}finally{Files.delete(temporary);}if(!Objects.equals(manifest.get("analysis_status"),warnings.isEmpty()?"completed":"completed-with-warnings")||!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText(root,warnings,false)))throw new IOException("Recomputed warning status/actions differ");
    }
    private static void emit(PrintStream out,String value){out.writeBytes((value+"\n").getBytes(StandardCharsets.UTF_8));}
}
